/* An avatar is a filled circle with white initials on it, so every one of
   these has to clear 3:1 against white — which is why they are the system's
   accents pulled a step down rather than the raw #FF8700 / #08A0F7 / #12CDD9,
   none of which carry white type. */
const AV={J:'#B85F00',T:'#0A72B8',M:'#0E8A60',E:'#8C3A98',D:'#8A6208',R:'#0A7D86',
          A:'#C2334F',K:'#525298',P:'#5C5CA2',N:'#0E7C8A',S:'#A03BB0',L:'#1A7A5C'};
const F=(n,i,e)=>({n,i,c:AV[i]||'#C24600',e:e||''});
/* email is optional on purpose: the attendee popover has to show both states,
   because only people with one can be sent the notes */

